import React, { useEffect, useState, useRef, useMemo } from 'react';
import { useNavigate, useParams, useSearchParams, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { resumeApi, templateApi } from '../services/api';
import { downloadResume } from '../utils/downloadResume';
import { useToast } from '../components/Toast';
import ResumeDocumentPreview from '../components/ResumeDocumentPreview';

const emptyResume = {
  title: '',
  candidateName: '',
  headline: '',
  summary: '',
  contactEmail: '',
  contactPhone: '',
  address: '',
  location: '',
  website: '',
  profilePhoto: '',
  skills: [],
  languages: [],
  references: [],
  education: [],
  experience: [],
  visibleToRecruiters: false,
  templateId: 6,
};

const sampleRichardSanchezResume = {
  title: 'Richard Sanchez - Marketing Manager',
  candidateName: 'RICHARD SANCHEZ',
  headline: 'MARKETING MANAGER',
  profilePhoto: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=400',
  summary: 'Creative and data-driven Marketing Manager with 7+ years of experience leading multi-disciplinary teams, scaling brand presence, and driving 40%+ year-over-year revenue growth through strategic omnichannel campaigns.',
  contactPhone: '+123-456-7890',
  contactEmail: 'hello@reallygreatsite.com',
  location: 'San Francisco, CA',
  address: '123 Anywhere St.',
  website: 'www.reallygreatsite.com',
  skills: [
    'Project Management',
    'Public Relations',
    'Team Leadership',
    'Time Management',
    'Strategic Growth',
    'Effective Communication',
    'Data Analytics',
    'Digital Marketing'
  ],
  languages: [
    'English (Fluent)',
    'French (Fluent)',
    'German (Basic)',
    'Spanish (Intermediate)'
  ],
  references: [
    {
      name: 'Estelle Darcy',
      company: 'Wardiere Inc.',
      title: 'CTO',
      phone: '123-456-7890',
      email: 'hello@reallygreatsite.com'
    }
  ],
  experience: [
    {
      company: 'Borcelle Studio',
      jobTitle: 'Marketing Manager & Specialist',
      startDate: '2023',
      endDate: 'PRESENT',
      current: true,
      description: '• Spearheaded and executed comprehensive marketing strategies and campaigns that elevated market reach by 45%.\n• Led, mentored, and managed a high-performing marketing team of 8 specialists.\n• Monitored brand consistency across digital channels and performance ad creative.',
      displayOrder: 0
    },
    {
      company: 'Fauget Studio',
      jobTitle: 'Senior Marketing Specialist',
      startDate: '2020',
      endDate: '2023',
      current: false,
      description: '• Created and managed a $1.8M marketing budget, optimizing ROI and reducing customer acquisition cost by 22%.\n• Conducted deep market research to identify emerging industry trends and competitor positioning.',
      displayOrder: 1
    },
    {
      company: 'Studio Shodwe',
      jobTitle: 'Marketing Coordinator',
      startDate: '2018',
      endDate: '2020',
      current: false,
      description: '• Developed and maintained strong partnerships with agencies and external media vendors.\n• Coordinated production schedules for omnichannel product release campaigns.',
      displayOrder: 2
    }
  ],
  education: [
    {
      institution: 'Wardiere University',
      degree: 'Master of Business Administration (MBA)',
      fieldOfStudy: 'School of Business',
      startDate: '2016',
      endDate: '2018',
      gpa: '3.9 / 4.0',
      displayOrder: 0
    },
    {
      institution: 'Wardiere University',
      degree: 'Bachelor of Science in Communications',
      fieldOfStudy: 'Department of Media Studies',
      startDate: '2012',
      endDate: '2016',
      gpa: '3.8 / 4.0',
      displayOrder: 1
    }
  ],
  visibleToRecruiters: true,
  templateId: 6
};

const ACTION_VERB_CATEGORIES = {
  '🚀 Leadership & Management': ['Spearheaded', 'Orchestrated', 'Directed', 'Mentored', 'Championed', 'Delegated', 'Governed'],
  '⚡ Execution & Engineering': ['Architected', 'Implemented', 'Engineered', 'Automated', 'Constructed', 'Designed', 'Revamped'],
  '📈 Growth & Optimization': ['Accelerated', 'Maximized', 'Optimized', 'Scaled', 'Generated', 'Expanded', 'Streamlined'],
  '🔍 Research & Analysis': ['Benchmarked', 'Evaluated', 'Diagnosed', 'Identified', 'Analyzed', 'Formulated', 'Synthesized']
};

export default function ResumeBuilder() {
  const { id } = useParams();
  const isNew = id === 'new';
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { user } = useAuth();
  const { addToast } = useToast();
  const fileInputRef = useRef(null);

  const [resume, setResume] = useState(emptyResume);
  const [skillInput, setSkillInput] = useState('');
  const [langInput, setLangInput] = useState('');
  const [viewMode, setViewMode] = useState('split'); // 'split' | 'editor' | 'preview'
  const [zoomLevel, setZoomLevel] = useState(100); // 80, 100, 120
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [errors, setErrors] = useState({});
  const [templates, setTemplates] = useState([]);
  const [activeVerbCategory, setActiveVerbCategory] = useState('🚀 Leadership & Management');
  const [showStrengthDrawer, setShowStrengthDrawer] = useState(false);

  // Accordion state
  const [openSections, setOpenSections] = useState({
    identity: true,
    photo: true,
    contact: true,
    summary: true,
    experience: true,
    education: true,
    skills: true,
    references: false,
    visibility: true
  });

  const toggleSection = (sectionKey) => {
    setOpenSections((prev) => ({ ...prev, [sectionKey]: !prev[sectionKey] }));
  };

  const expandAllSections = () => {
    setOpenSections({
      identity: true,
      photo: true,
      contact: true,
      summary: true,
      experience: true,
      education: true,
      skills: true,
      references: true,
      visibility: true
    });
  };

  const collapseAllSections = () => {
    setOpenSections({
      identity: false,
      photo: false,
      contact: false,
      summary: false,
      experience: false,
      education: false,
      skills: false,
      references: false,
      visibility: false
    });
  };

  useEffect(() => {
    templateApi.getAll().then((res) => setTemplates(res.data || []));
  }, []);

  useEffect(() => {
    if (!isNew) {
      resumeApi.getById(id)
        .then((res) => {
          const loadedData = res.data || {};
          setResume({
            ...emptyResume,
            ...loadedData,
            templateId: loadedData.templateId ? Number(loadedData.templateId) : 6,
          });
        })
        .catch(() => setError('Could not load resume.'));
    } else {
      const templateParam = searchParams.get('template');
      const templateId = templateParam ? Number(templateParam) : 6;
      setResume({
        ...emptyResume,
        candidateName: user?.fullName || '',
        contactEmail: user?.email || '',
        templateId,
      });
    }
  }, [id, isNew, user, searchParams]);

  const selectedTemplate = templates.find((t) => Number(t.id) === Number(resume.templateId)) || templates.find((t) => Number(t.id) === 6) || templates[0];

  const update = (field, value) => {
    setResume((prev) => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors((prev) => {
        const next = { ...prev };
        delete next[field];
        return next;
      });
    }
    if (error) setError('');
  };

  const handlePhotoUpload = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        update('profilePhoto', reader.result);
        addToast('Profile photo updated!', 'success');
      };
      reader.readAsDataURL(file);
    }
  };

  const loadSampleData = () => {
    setResume({
      ...sampleRichardSanchezResume,
      id: resume.id,
      templateId: resume.templateId || 6,
    });
    setErrors({});
    setError('');
    addToast('Sample resume data loaded!', 'success');
  };

  const addSkill = () => {
    if (skillInput.trim() && !resume.skills?.includes(skillInput.trim())) {
      update('skills', [...(resume.skills || []), skillInput.trim()]);
      addToast(`Added skill "${skillInput.trim()}"`, 'info', 2000);
    }
    setSkillInput('');
  };

  const removeSkill = (skill) => update('skills', (resume.skills || []).filter((s) => s !== skill));

  const addLanguage = () => {
    if (langInput.trim() && !resume.languages?.includes(langInput.trim())) {
      update('languages', [...(resume.languages || []), langInput.trim()]);
      addToast(`Added language "${langInput.trim()}"`, 'info', 2000);
    }
    setLangInput('');
  };

  const removeLanguage = (lang) => update('languages', (resume.languages || []).filter((l) => l !== lang));

  const addReference = () => update('references', [...(resume.references || []), {
    name: '', company: '', title: '', phone: '', email: ''
  }]);

  const updateReference = (index, field, value) => {
    const list = [...(resume.references || [])];
    list[index] = { ...list[index], [field]: value };
    update('references', list);
  };

  const removeReference = (index) => update('references', (resume.references || []).filter((_, i) => i !== index));

  const addEducation = () => update('education', [...resume.education, {
    institution: '', degree: '', fieldOfStudy: '', startDate: '', endDate: '', gpa: '', displayOrder: resume.education.length,
  }]);

  const updateEducation = (index, field, value) => {
    const list = [...resume.education];
    list[index] = { ...list[index], [field]: value };
    update('education', list);
  };

  const removeEducation = (index) => update('education', resume.education.filter((_, i) => i !== index));

  const addExperience = () => update('experience', [...resume.experience, {
    company: '', jobTitle: '', startDate: '', endDate: '', current: false, description: '', displayOrder: resume.experience.length,
  }]);

  const updateExperience = (index, field, value) => {
    const list = [...resume.experience];
    list[index] = { ...list[index], [field]: value };
    update('experience', list);
  };

  const removeExperience = (index) => update('experience', resume.experience.filter((_, i) => i !== index));

  // Insert Action Verb to the latest or specific experience item
  const handleInsertVerb = (verb) => {
    const expList = [...(resume.experience || [])];
    if (expList.length === 0) {
      expList.push({
        company: '',
        jobTitle: '',
        startDate: '',
        endDate: '',
        current: true,
        description: `• ${verb} `,
        displayOrder: 0
      });
    } else {
      const lastIdx = expList.length - 1;
      const currentDesc = expList[lastIdx].description || '';
      const bulletPrefix = currentDesc && !currentDesc.endsWith('\n') ? '\n• ' : currentDesc ? '• ' : '• ';
      expList[lastIdx] = {
        ...expList[lastIdx],
        description: `${currentDesc}${bulletPrefix}${verb} `
      };
    }
    update('experience', expList);
    addToast(`Inserted verb "${verb}" into experience!`, 'info', 2000);
  };

  // Real-time ATS Strength Calculation
  const resumeStrengthBreakdown = useMemo(() => {
    const checks = [
      {
        id: 'identity',
        label: 'Resume Title & Full Name',
        points: 15,
        done: Boolean(resume.title?.trim() && resume.candidateName?.trim()),
        tip: 'Add a descriptive title and your full legal name.'
      },
      {
        id: 'contact',
        label: 'Complete Contact Details (Email + Phone)',
        points: 15,
        done: Boolean(resume.contactEmail?.trim() && resume.contactPhone?.trim()),
        tip: 'Ensure recruiters have both phone and valid email.'
      },
      {
        id: 'summary',
        label: 'Professional Summary (> 40 chars)',
        points: 15,
        done: Boolean(resume.summary?.trim() && resume.summary.length >= 40),
        tip: 'Write a strong 2-3 sentence elevator pitch.'
      },
      {
        id: 'experience',
        label: 'Work Experience with Details',
        points: 20,
        done: Boolean(resume.experience?.length > 0 && resume.experience[0].company && resume.experience[0].description),
        tip: 'Add at least 1 job role with impactful bullet points.'
      },
      {
        id: 'education',
        label: 'Education & Degree',
        points: 15,
        done: Boolean(resume.education?.length > 0 && resume.education[0].institution),
        tip: 'List your highest degree and institution.'
      },
      {
        id: 'skills',
        label: 'At Least 4 Core Skills',
        points: 10,
        done: Boolean(resume.skills?.length >= 4),
        tip: 'Add relevant industry skills and technologies.'
      },
      {
        id: 'visibility',
        label: 'Recruiter Searchable Enabled',
        points: 10,
        done: Boolean(resume.visibleToRecruiters),
        tip: 'Turn on recruiter visibility to be discovered by employers.'
      }
    ];

    const totalScore = checks.reduce((acc, c) => acc + (c.done ? c.points : 0), 0);
    return { checks, totalScore };
  }, [resume]);

  const validateForm = () => {
    const validationErrors = {};
    if (!resume.title || !resume.title.trim()) {
      validationErrors.title = 'Please enter a resume title.';
    }
    if (!resume.candidateName || !resume.candidateName.trim()) {
      validationErrors.candidateName = 'Please enter your full name.';
    }
    if (!resume.contactEmail || !resume.contactEmail.trim()) {
      validationErrors.contactEmail = 'Please enter your email address.';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(resume.contactEmail.trim())) {
      validationErrors.contactEmail = 'Please enter a valid email address.';
    }
    return validationErrors;
  };

  const handleSave = async () => {
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      setError('Please fill in required fields (Title, Name, Email) before saving.');
      addToast('Please fill in required fields (* Title, Name, Email)', 'error');
      return;
    }

    setSaving(true);
    setError('');
    setErrors({});
    try {
      if (isNew) {
        const res = await resumeApi.create(resume);
        addToast('Resume created successfully!', 'success');
        navigate(`/resume/${res.data.id}`);
      } else {
        await resumeApi.update(id, resume);
        addToast('Resume saved successfully!', 'success');
        navigate('/dashboard');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Could not save resume.');
      addToast('Could not save resume', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleDownload = () => {
    addToast('Preparing PDF download / print layout…', 'info');
    downloadResume(resume);
  };

  const isFormIncomplete = !resume.title?.trim() || !resume.candidateName?.trim() || !resume.contactEmail?.trim();

  return (
    <div className="builder-fullscreen-wrapper">
      {/* Top Application Control Toolbar */}
      <header className="builder-top-toolbar">
        <div className="toolbar-left">
          <Link to="/dashboard" className="toolbar-back-btn">
            ← Dashboard
          </Link>
          <div className="toolbar-title-box">
            <h2>{isNew ? 'Create New Resume' : 'Edit Resume'}</h2>
            <span className="toolbar-template-pill">
              {selectedTemplate?.name || 'Executive Timeline'}
            </span>
          </div>
        </div>

        <div className="toolbar-center">
          <div className="view-mode-pill">
            <button
              type="button"
              className={`mode-btn ${viewMode === 'split' ? 'active' : ''}`}
              onClick={() => setViewMode('split')}
              title="Split View (Form + Live Sheet)"
            >
              ◫ Split View
            </button>
            <button
              type="button"
              className={`mode-btn ${viewMode === 'editor' ? 'active' : ''}`}
              onClick={() => setViewMode('editor')}
              title="Editor Only"
            >
              📝 Form Only
            </button>
            <button
              type="button"
              className={`mode-btn ${viewMode === 'preview' ? 'active' : ''}`}
              onClick={() => setViewMode('preview')}
              title="Live Sheet Preview"
            >
              👁️ Sheet Preview
            </button>
          </div>
        </div>

        <div className="toolbar-right">
          {/* Interactive ATS Score Meter Button */}
          <button
            type="button"
            className="btn-ats-meter-pill"
            onClick={() => setShowStrengthDrawer(!showStrengthDrawer)}
            title="Click to view ATS strength tips"
          >
            <span className="ats-pulse-dot" style={{
              background: resumeStrengthBreakdown.totalScore >= 80 ? '#10b981' : resumeStrengthBreakdown.totalScore >= 50 ? '#f59e0b' : '#ef4444'
            }}></span>
            <span className="ats-score-text">ATS Score: <strong>{resumeStrengthBreakdown.totalScore}%</strong></span>
          </button>

          <button
            type="button"
            className="btn-toolbar-sample"
            onClick={loadSampleData}
            title="Pre-fill form with professional sample content"
          >
            ✨ Fill Sample Data
          </button>

          <button
            type="button"
            className="btn-toolbar-pdf"
            onClick={handleDownload}
            title="Download PDF"
          >
            📥 Download PDF
          </button>

          <button
            type="button"
            className="btn-toolbar-save"
            onClick={handleSave}
            disabled={saving}
          >
            {saving ? 'Saving…' : '💾 Save Resume'}
          </button>
        </div>
      </header>

      {/* Main Split-Screen Workspace */}
      <div className={`builder-workspace view-${viewMode}`}>
        {/* LEFT COLUMN: Interactive Form Sections */}
        {(viewMode === 'split' || viewMode === 'editor') && (
          <div className="builder-editor-pane">
            {isFormIncomplete && (
              <div className="empty-details-hint">
                ℹ️ <strong>Quick Start:</strong> Fill required fields (* Title, Full Name, Email) or click <strong>"✨ Fill Sample Data"</strong> in the top toolbar to auto-populate.
              </div>
            )}

            {error && <div className="error-banner">{error}</div>}

            {/* Accordion Master Controls */}
            <div className="accordion-master-bar">
              <span className="accordion-label">Form Sections ({Object.values(openSections).filter(Boolean).length}/9 Open)</span>
              <div className="accordion-toggle-actions">
                <button type="button" className="btn-text-action" onClick={expandAllSections}>Expand All</button>
                <span className="divider-slash">/</span>
                <button type="button" className="btn-text-action" onClick={collapseAllSections}>Collapse All</button>
              </div>
            </div>

            {/* Template & Color Selector Card */}
            <section className="form-section-pro template-select-section">
              <div className="section-head-clickable" onClick={() => toggleSection('template')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">🎨</span>
                  <div className="sec-titles">
                    <h3>Template & Visual Layout</h3>
                    <p className="sec-desc">Choose your visual typography and presentation scheme</p>
                  </div>
                </div>
              </div>
              <div className="section-body-collapsible">
                <div className="template-select-row">
                  <select
                    value={resume.templateId || 6}
                    onChange={(e) => {
                      update('templateId', Number(e.target.value));
                      addToast(`Switched template to ${templates.find(t => t.id === Number(e.target.value))?.name || 'Selected'}`, 'info', 2000);
                    }}
                    className="template-select-dropdown"
                  >
                    {templates.map((t) => (
                      <option key={t.id} value={t.id}>
                        {t.name} ({t.industryCategory}) — {t.layoutStyle}
                      </option>
                    ))}
                  </select>
                  <Link to="/templates" className="btn-secondary-link">
                    🎨 Browse Full Library
                  </Link>
                </div>
              </div>
            </section>

            {/* 1. Resume Identity Section */}
            <section className="form-section-pro">
              <div className="section-head-clickable" onClick={() => toggleSection('identity')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">🏷️</span>
                  <div className="sec-titles">
                    <h3>Resume Identity & Headline</h3>
                    <p className="sec-desc">Internal title and professional role branding</p>
                  </div>
                </div>
                <div className="sec-header-right">
                  {resume.title && <span className="sec-status-done">✓ Filled</span>}
                  <span className="accordion-caret">{openSections.identity ? '▲' : '▼'}</span>
                </div>
              </div>

              {openSections.identity && (
                <div className="section-body-collapsible">
                  <label>
                    Resume Title (e.g. "Senior Marketing Specialist - 2026") <span className="required-mark">*</span>
                  </label>
                  <input
                    className={errors.title ? 'input-error' : ''}
                    value={resume.title}
                    onChange={(e) => update('title', e.target.value)}
                    placeholder="e.g. Richard Sanchez - Marketing Resume"
                  />
                  {errors.title && <span className="field-error-text">{errors.title}</span>}

                  <label style={{ marginTop: '12px' }}>Headline / Target Professional Title</label>
                  <input
                    value={resume.headline}
                    onChange={(e) => update('headline', e.target.value)}
                    placeholder="e.g. MARKETING MANAGER & STRATEGIST"
                  />
                </div>
              )}
            </section>

            {/* 2. Profile Photo (Visible for Timeline / Executive Templates) */}
            <section className="form-section-pro">
              <div className="section-head-clickable" onClick={() => toggleSection('photo')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">👤</span>
                  <div className="sec-titles">
                    <h3>Profile Photo / Avatar</h3>
                    <p className="sec-desc">Displays in circular badge on Executive Timeline templates</p>
                  </div>
                </div>
                <div className="sec-header-right">
                  {resume.profilePhoto && <span className="sec-status-done">✓ Photo Set</span>}
                  <span className="accordion-caret">{openSections.photo ? '▲' : '▼'}</span>
                </div>
              </div>

              {openSections.photo && (
                <div className="section-body-collapsible">
                  <div className="photo-upload-container">
                    <div className="photo-avatar-preview">
                      <img
                        src={resume.profilePhoto || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=400'}
                        alt="Avatar preview"
                      />
                    </div>
                    <div className="photo-upload-controls">
                      <input
                        type="file"
                        ref={fileInputRef}
                        accept="image/*"
                        style={{ display: 'none' }}
                        onChange={handlePhotoUpload}
                      />
                      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                        <button
                          type="button"
                          className="btn-secondary btn-sm"
                          onClick={() => fileInputRef.current?.click()}
                        >
                          📁 Upload File
                        </button>
                        <button
                          type="button"
                          className="btn-secondary btn-sm"
                          onClick={() => {
                            update('profilePhoto', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=400');
                            addToast('Sample portrait loaded', 'info', 2000);
                          }}
                        >
                          Use Sample Photo
                        </button>
                        {resume.profilePhoto && (
                          <button
                            type="button"
                            className="btn-link danger btn-sm"
                            onClick={() => update('profilePhoto', '')}
                          >
                            Remove
                          </button>
                        )}
                      </div>
                      <input
                        style={{ marginTop: '10px', fontSize: '0.85rem' }}
                        placeholder="Or enter direct image URL (https://...)"
                        value={resume.profilePhoto || ''}
                        onChange={(e) => update('profilePhoto', e.target.value)}
                      />
                    </div>
                  </div>
                </div>
              )}
            </section>

            {/* 3. Personal & Contact Details */}
            <section className="form-section-pro">
              <div className="section-head-clickable" onClick={() => toggleSection('contact')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">📬</span>
                  <div className="sec-titles">
                    <h3>Personal & Contact Details</h3>
                    <p className="sec-desc">Email, phone, location, and portfolio link</p>
                  </div>
                </div>
                <div className="sec-header-right">
                  {resume.candidateName && resume.contactEmail && <span className="sec-status-done">✓ Filled</span>}
                  <span className="accordion-caret">{openSections.contact ? '▲' : '▼'}</span>
                </div>
              </div>

              {openSections.contact && (
                <div className="section-body-collapsible">
                  <div className="form-row">
                    <div>
                      <label>Full Name <span className="required-mark">*</span></label>
                      <input
                        className={errors.candidateName ? 'input-error' : ''}
                        value={resume.candidateName}
                        onChange={(e) => update('candidateName', e.target.value)}
                        placeholder="e.g. RICHARD SANCHEZ"
                      />
                      {errors.candidateName && <span className="field-error-text">{errors.candidateName}</span>}
                    </div>
                    <div>
                      <label>Email Address <span className="required-mark">*</span></label>
                      <input
                        type="email"
                        className={errors.contactEmail ? 'input-error' : ''}
                        value={resume.contactEmail}
                        onChange={(e) => update('contactEmail', e.target.value)}
                        placeholder="e.g. hello@reallygreatsite.com"
                      />
                      {errors.contactEmail && <span className="field-error-text">{errors.contactEmail}</span>}
                    </div>
                  </div>

                  <div className="form-row">
                    <div>
                      <label>Phone Number</label>
                      <input
                        value={resume.contactPhone}
                        onChange={(e) => update('contactPhone', e.target.value)}
                        placeholder="e.g. +123-456-7890"
                      />
                    </div>
                    <div>
                      <label>City & Country</label>
                      <input
                        value={resume.location}
                        onChange={(e) => update('location', e.target.value)}
                        placeholder="e.g. San Francisco, CA"
                      />
                    </div>
                  </div>

                  <div className="form-row">
                    <div>
                      <label>Street Address</label>
                      <input
                        value={resume.address}
                        onChange={(e) => update('address', e.target.value)}
                        placeholder="e.g. 123 Anywhere St."
                      />
                    </div>
                    <div>
                      <label>Portfolio / Website</label>
                      <input
                        value={resume.website}
                        onChange={(e) => update('website', e.target.value)}
                        placeholder="e.g. www.reallygreatsite.com"
                      />
                    </div>
                  </div>
                </div>
              )}
            </section>

            {/* 4. Professional Summary */}
            <section className="form-section-pro">
              <div className="section-head-clickable" onClick={() => toggleSection('summary')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">📝</span>
                  <div className="sec-titles">
                    <h3>Professional Summary / Profile</h3>
                    <p className="sec-desc">Executive elevator pitch summarizing career highlights</p>
                  </div>
                </div>
                <div className="sec-header-right">
                  {resume.summary?.length > 30 && <span className="sec-status-done">✓ Ready</span>}
                  <span className="accordion-caret">{openSections.summary ? '▲' : '▼'}</span>
                </div>
              </div>

              {openSections.summary && (
                <div className="section-body-collapsible">
                  <label>Summary Statement</label>
                  <textarea
                    rows={4}
                    value={resume.summary}
                    onChange={(e) => update('summary', e.target.value)}
                    placeholder="Write a concise overview of your background, industry experience, leadership capabilities, and major achievements..."
                  />
                  <div className="input-helper-row">
                    <span className="char-count-text">{(resume.summary || '').length} characters</span>
                    <span className="tip-text">💡 Tip: 150-300 characters is ideal for ATS scoring.</span>
                  </div>
                </div>
              )}
            </section>

            {/* 5. Work Experience with Interactive Action Verbs Drawer */}
            <section className="form-section-pro">
              <div className="section-head-clickable" onClick={() => toggleSection('experience')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">💼</span>
                  <div className="sec-titles">
                    <h3>Work Experience ({resume.experience.length})</h3>
                    <p className="sec-desc">Roles, timeline dates, and quantified accomplishment bullets</p>
                  </div>
                </div>
                <div className="sec-header-right">
                  {resume.experience.length > 0 && <span className="sec-status-done">✓ {resume.experience.length} Added</span>}
                  <span className="accordion-caret">{openSections.experience ? '▲' : '▼'}</span>
                </div>
              </div>

              {openSections.experience && (
                <div className="section-body-collapsible">
                  {/* Action Verbs Suggester Widget */}
                  <div className="action-verbs-widget">
                    <div className="verbs-header">
                      <span className="verbs-badge">⚡ Power Action Verbs</span>
                      <span className="verbs-hint">Click any verb to insert directly into experience</span>
                    </div>

                    <div className="verb-category-tabs">
                      {Object.keys(ACTION_VERB_CATEGORIES).map((cat) => (
                        <button
                          key={cat}
                          type="button"
                          className={`verb-tab-btn ${activeVerbCategory === cat ? 'active' : ''}`}
                          onClick={() => setActiveVerbCategory(cat)}
                        >
                          {cat}
                        </button>
                      ))}
                    </div>

                    <div className="verb-chips-row">
                      {ACTION_VERB_CATEGORIES[activeVerbCategory]?.map((verb) => (
                        <button
                          key={verb}
                          type="button"
                          className="verb-chip"
                          onClick={() => handleInsertVerb(verb)}
                          title={`Click to insert "+ • ${verb} "`}
                        >
                          + {verb}
                        </button>
                      ))}
                    </div>
                  </div>

                  {resume.experience.map((exp, i) => (
                    <div className="entry-card-pro" key={i}>
                      <div className="entry-card-header">
                        <span className="entry-index-badge">Role #{i + 1}</span>
                        <button
                          type="button"
                          className="btn-entry-remove"
                          onClick={() => removeExperience(i)}
                          title="Remove this role"
                        >
                          ✕ Remove
                        </button>
                      </div>

                      <div className="form-row">
                        <input
                          placeholder="Company (e.g. Borcelle Studio)"
                          value={exp.company}
                          onChange={(e) => updateExperience(i, 'company', e.target.value)}
                        />
                        <input
                          placeholder="Job Title (e.g. Marketing Manager)"
                          value={exp.jobTitle}
                          onChange={(e) => updateExperience(i, 'jobTitle', e.target.value)}
                        />
                      </div>

                      <div className="form-row">
                        <input
                          placeholder="Start Date (e.g. 2023)"
                          value={exp.startDate}
                          onChange={(e) => updateExperience(i, 'startDate', e.target.value)}
                        />
                        <input
                          placeholder="End Date (e.g. 2026 or Present)"
                          value={exp.endDate}
                          onChange={(e) => updateExperience(i, 'endDate', e.target.value)}
                          disabled={exp.current}
                        />
                      </div>

                      <label className="checkbox-label">
                        <input
                          type="checkbox"
                          checked={exp.current}
                          onChange={(e) => updateExperience(i, 'current', e.target.checked)}
                        />
                        Currently working here (shows as <strong>PRESENT</strong>)
                      </label>

                      <label style={{ marginTop: '10px' }}>
                        Accomplishment Bullet Points (Use • for bullets, one per line)
                      </label>
                      <textarea
                        rows={4}
                        value={exp.description}
                        onChange={(e) => updateExperience(i, 'description', e.target.value)}
                        placeholder="• Spearheaded new product launch increasing ARR by 35%&#10;• Mentored a team of 6 junior engineers&#10;• Optimized database queries cutting latency by 50%"
                      />
                    </div>
                  ))}

                  <button type="button" className="btn-add-entry" onClick={addExperience}>
                    + Add Another Work Experience Role
                  </button>
                </div>
              )}
            </section>

            {/* 6. Education Section */}
            <section className="form-section-pro">
              <div className="section-head-clickable" onClick={() => toggleSection('education')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">🎓</span>
                  <div className="sec-titles">
                    <h3>Education ({resume.education.length})</h3>
                    <p className="sec-desc">Degrees, universities, fields of study, and honors</p>
                  </div>
                </div>
                <div className="sec-header-right">
                  {resume.education.length > 0 && <span className="sec-status-done">✓ {resume.education.length} Added</span>}
                  <span className="accordion-caret">{openSections.education ? '▲' : '▼'}</span>
                </div>
              </div>

              {openSections.education && (
                <div className="section-body-collapsible">
                  {resume.education.map((edu, i) => (
                    <div className="entry-card-pro" key={i}>
                      <div className="entry-card-header">
                        <span className="entry-index-badge">Degree #{i + 1}</span>
                        <button
                          type="button"
                          className="btn-entry-remove"
                          onClick={() => removeEducation(i)}
                        >
                          ✕ Remove
                        </button>
                      </div>

                      <div className="form-row">
                        <input
                          placeholder="Degree (e.g. Master of Business Administration)"
                          value={edu.degree}
                          onChange={(e) => updateEducation(i, 'degree', e.target.value)}
                        />
                        <input
                          placeholder="Institution (e.g. Stanford University)"
                          value={edu.institution}
                          onChange={(e) => updateEducation(i, 'institution', e.target.value)}
                        />
                      </div>

                      <div className="form-row">
                        <input
                          placeholder="Department / Major (e.g. School of Business)"
                          value={edu.fieldOfStudy}
                          onChange={(e) => updateEducation(i, 'fieldOfStudy', e.target.value)}
                        />
                        <input
                          placeholder="GPA / Honors (e.g. 3.9 / 4.0)"
                          value={edu.gpa}
                          onChange={(e) => updateEducation(i, 'gpa', e.target.value)}
                        />
                      </div>

                      <div className="form-row">
                        <input
                          placeholder="Start Year (e.g. 2018)"
                          value={edu.startDate}
                          onChange={(e) => updateEducation(i, 'startDate', e.target.value)}
                        />
                        <input
                          placeholder="End Year (e.g. 2020)"
                          value={edu.endDate}
                          onChange={(e) => updateEducation(i, 'endDate', e.target.value)}
                        />
                      </div>
                    </div>
                  ))}

                  <button type="button" className="btn-add-entry" onClick={addEducation}>
                    + Add Another Degree / Certification
                  </button>
                </div>
              )}
            </section>

            {/* 7. Skills & Languages */}
            <section className="form-section-pro">
              <div className="section-head-clickable" onClick={() => toggleSection('skills')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">⚡</span>
                  <div className="sec-titles">
                    <h3>Skills & Languages ({(resume.skills || []).length} Skills)</h3>
                    <p className="sec-desc">Core competencies, technical proficiencies, and spoken languages</p>
                  </div>
                </div>
                <div className="sec-header-right">
                  {(resume.skills || []).length >= 3 && <span className="sec-status-done">✓ Good</span>}
                  <span className="accordion-caret">{openSections.skills ? '▲' : '▼'}</span>
                </div>
              </div>

              {openSections.skills && (
                <div className="section-body-collapsible">
                  <label>Core Skills (Type skill name and hit Enter or click Add)</label>
                  <div className="skill-input-row">
                    <input
                      value={skillInput}
                      onChange={(e) => setSkillInput(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), addSkill())}
                      placeholder="e.g. React, Python, Project Management, Digital Marketing"
                    />
                    <button type="button" className="btn-primary" onClick={addSkill}>+ Add Skill</button>
                  </div>

                  <div className="skill-tags">
                    {(resume.skills || []).map((s) => (
                      <span key={s} className="skill-tag-pro">
                        {s}
                        <button type="button" onClick={() => removeSkill(s)} aria-label={`Remove ${s}`}>&times;</button>
                      </span>
                    ))}
                  </div>

                  <label style={{ marginTop: '20px' }}>Languages Spoken</label>
                  <div className="skill-input-row">
                    <input
                      value={langInput}
                      onChange={(e) => setLangInput(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), addLanguage())}
                      placeholder="e.g. English (Fluent) or Spanish (Native)"
                    />
                    <button type="button" className="btn-primary" onClick={addLanguage}>+ Add Language</button>
                  </div>

                  <div className="skill-tags">
                    {(resume.languages || []).map((l) => (
                      <span key={typeof l === 'object' ? l.name : l} className="skill-tag-lang">
                        {typeof l === 'object' ? `${l.name} (${l.proficiency})` : l}
                        <button type="button" onClick={() => removeLanguage(l)} aria-label="Remove language">&times;</button>
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </section>

            {/* 8. Professional References */}
            <section className="form-section-pro">
              <div className="section-head-clickable" onClick={() => toggleSection('references')}>
                <div className="section-title-wrapper">
                  <span className="sec-icon">👥</span>
                  <div className="sec-titles">
                    <h3>References ({(resume.references || []).length})</h3>
                    <p className="sec-desc">Professional testimonials and recommendation contacts</p>
                  </div>
                </div>
                <div className="sec-header-right">
                  <span className="accordion-caret">{openSections.references ? '▲' : '▼'}</span>
                </div>
              </div>

              {openSections.references && (
                <div className="section-body-collapsible">
                  {(resume.references || []).map((ref, i) => (
                    <div className="entry-card-pro" key={i}>
                      <div className="entry-card-header">
                        <span className="entry-index-badge">Reference #{i + 1}</span>
                        <button
                          type="button"
                          className="btn-entry-remove"
                          onClick={() => removeReference(i)}
                        >
                          ✕ Remove
                        </button>
                      </div>

                      <div className="form-row">
                        <input
                          placeholder="Referee Full Name (e.g. Estelle Darcy)"
                          value={ref.name}
                          onChange={(e) => updateReference(i, 'name', e.target.value)}
                        />
                        <input
                          placeholder="Company & Role (e.g. Wardiere Inc. / CTO)"
                          value={ref.title ? `${ref.company || ''}${ref.company && ref.title ? ' / ' : ''}${ref.title}` : ref.company}
                          onChange={(e) => {
                            const parts = e.target.value.split('/');
                            updateReference(i, 'company', parts[0]?.trim() || '');
                            updateReference(i, 'title', parts[1]?.trim() || '');
                          }}
                        />
                      </div>

                      <div className="form-row">
                        <input
                          placeholder="Phone (e.g. 123-456-7890)"
                          value={ref.phone}
                          onChange={(e) => updateReference(i, 'phone', e.target.value)}
                        />
                        <input
                          placeholder="Email (e.g. hello@reallygreatsite.com)"
                          value={ref.email}
                          onChange={(e) => updateReference(i, 'email', e.target.value)}
                        />
                      </div>
                    </div>
                  ))}

                  <button type="button" className="btn-add-entry" onClick={addReference}>
                    + Add Reference Contact
                  </button>
                </div>
              )}
            </section>

            {/* 9. Recruiter Visibility Toggle */}
            <section className="form-section-pro visibility-card-pro">
              <label className="checkbox-label-prominent">
                <input
                  type="checkbox"
                  checked={resume.visibleToRecruiters}
                  onChange={(e) => {
                    update('visibleToRecruiters', e.target.checked);
                    addToast(
                      e.target.checked ? 'Resume is now searchable by recruiters!' : 'Resume is private',
                      'info',
                      2500
                    );
                  }}
                />
                <div className="checkbox-text-wrapper">
                  <span className="checkbox-title">🎯 Make this resume searchable & visible to verified recruiters</span>
                  <span className="checkbox-subtitle">Allows verified employers and hiring managers to discover and contact you.</span>
                </div>
              </label>
            </section>

            {/* Bottom Actions Bar */}
            <div className="form-bottom-actions">
              <button type="button" className="btn-secondary-glass" onClick={handleDownload}>
                📥 Download / Print PDF
              </button>
              <button className="btn-primary-glow" onClick={handleSave} disabled={saving}>
                {saving ? 'Saving…' : '💾 Save Resume'}
              </button>
            </div>
          </div>
        )}

        {/* RIGHT COLUMN: Real-Time Live Visual Resume Sheet */}
        {(viewMode === 'split' || viewMode === 'preview') && (
          <div className="builder-preview-pane">
            {/* Interactive Preview Controls Bar */}
            <div className="preview-pane-header">
              <div className="preview-status-box">
                <span className="live-indicator-pulse"></span>
                <span className="live-badge-text">LIVE REAL-TIME SHEET</span>
              </div>

              {/* Zoom Controls */}
              <div className="preview-zoom-controls">
                <button
                  type="button"
                  className="btn-zoom"
                  onClick={() => setZoomLevel((prev) => Math.max(70, prev - 10))}
                  title="Zoom Out"
                >
                  −
                </button>
                <span className="zoom-level-text">{zoomLevel}%</span>
                <button
                  type="button"
                  className="btn-zoom"
                  onClick={() => setZoomLevel((prev) => Math.min(130, prev + 10))}
                  title="Zoom In"
                >
                  +
                </button>
                <button
                  type="button"
                  className="btn-zoom-reset"
                  onClick={() => setZoomLevel(100)}
                  title="Reset Zoom"
                >
                  Fit
                </button>
              </div>

              <div className="preview-quick-download">
                <button
                  type="button"
                  className="btn-preview-dl"
                  onClick={handleDownload}
                  title="Download PDF"
                >
                  📥 Download PDF
                </button>
              </div>
            </div>

            <div className="preview-sheet-scroller">
              <div
                className="preview-zoom-wrapper"
                style={{
                  transform: `scale(${zoomLevel / 100})`,
                  transformOrigin: 'top center',
                  transition: 'transform 0.15s ease'
                }}
              >
                <ResumeDocumentPreview resume={resume} template={selectedTemplate} />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* ATS Strength Checklist Popover / Drawer */}
      {showStrengthDrawer && (
        <div className="ats-drawer-overlay" onClick={() => setShowStrengthDrawer(false)}>
          <div className="ats-drawer-card" onClick={(e) => e.stopPropagation()}>
            <div className="ats-drawer-header">
              <div className="drawer-score-ring">
                <span className="drawer-score-number">{resumeStrengthBreakdown.totalScore}%</span>
              </div>
              <div className="drawer-header-text">
                <h3>ATS Resume Strength Meter</h3>
                <p>Complete actionable items to maximize interview callback rates.</p>
              </div>
              <button
                type="button"
                className="drawer-close-btn"
                onClick={() => setShowStrengthDrawer(false)}
              >
                ✕
              </button>
            </div>

            <div className="ats-drawer-body">
              {resumeStrengthBreakdown.checks.map((check) => (
                <div key={check.id} className={`ats-check-row ${check.done ? 'done' : 'pending'}`}>
                  <span className="check-icon">{check.done ? '✅' : '⚪'}</span>
                  <div className="check-info">
                    <div className="check-title-row">
                      <span className="check-name">{check.label}</span>
                      <span className="check-pts">+{check.points}%</span>
                    </div>
                    <p className="check-tip">{check.tip}</p>
                  </div>
                </div>
              ))}
            </div>

            <div className="ats-drawer-footer">
              <button
                type="button"
                className="btn-primary btn-sm"
                style={{ width: '100%' }}
                onClick={() => setShowStrengthDrawer(false)}
              >
                Continue Editing
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
